import numpy as np

def sigmoid(x):
    return 1 / (1 + np.exp(-x))

def sigmoid_derivative(x):
    s = sigmoid(x)
    return s * (1 - s)

test_inputs = np.array([-10, -5, -2, 0, 2, 5, 10])

print("Input | Sigmoid output | Sigmoid gradient")
for x in test_inputs:
    output = sigmoid(x)
    gradient = sigmoid_derivative(x)
    print(f"  {x:5.1f} |     {output:.4f}     |    {gradient:.6f}")

print("\nNotice the gradient is largest near input 0, and shrinks dramatically toward the extremes,")
print("exactly the vanishing gradient problem this topic covers")
